CREATE DATABASE IF NOT EXISTS benest CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE benest;
CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), INDEX(status));
CREATE TABLE clients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, company VARCHAR(180) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40), website VARCHAR(255), address TEXT, notes TEXT, status ENUM('active','inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status));
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id INT UNSIGNED NOT NULL, manager_id INT UNSIGNED NULL, name VARCHAR(180) NOT NULL, description TEXT, start_date DATE, due_date DATE, actual_completion_date DATE NULL, budget DECIMAL(12,2) DEFAULT 0, status ENUM('Planning','Not Started','In Progress','On Hold','Under Review','Testing','Completed','Cancelled') DEFAULT 'Planning', priority ENUM('Low','Medium','High','Critical') DEFAULT 'Medium', technologies VARCHAR(255), repository_url VARCHAR(255), development_url VARCHAR(255), staging_url VARCHAR(255), production_url VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(manager_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(status), INDEX(due_date));
CREATE TABLE milestones (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id INT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, start_date DATE, due_date DATE, status ENUM('Planned','In Progress','Completed') DEFAULT 'Planned', progress TINYINT UNSIGNED DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, INDEX(project_id));
CREATE TABLE tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id INT UNSIGNED NOT NULL, milestone_id INT UNSIGNED NULL, assigned_to INT UNSIGNED NULL, parent_id INT UNSIGNED NULL, title VARCHAR(200) NOT NULL, description TEXT, priority ENUM('Low','Medium','High','Critical') DEFAULT 'Medium', status ENUM('Backlog','To Do','In Progress','Code Review','Testing','Done') DEFAULT 'Backlog', start_date DATE, due_date DATE, estimated_hours DECIMAL(8,2) DEFAULT 0, actual_hours DECIMAL(8,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(milestone_id) REFERENCES milestones(id) ON DELETE SET NULL, FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(parent_id) REFERENCES tasks(id) ON DELETE CASCADE, INDEX(status), INDEX(due_date));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(255) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id INT UNSIGNED NULL, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(created_at));
